<script>
  (function() {
    const submitBtn = document.getElementById('submitBtn');
    const legalConsent = document.getElementById('legalConsent');

    if (submitBtn && legalConsent) {
      submitBtn.addEventListener('click', function(e) {
        e.preventDefault();
        if (!legalConsent.checked) {
          alert('Mohon centang persetujuan keabsahan data dan dokumen terlebih dahulu.');
          return;
        }

        const originalText = submitBtn.innerHTML;
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<span class="material-symbols-outlined animate-spin text-[20px]">sync</span> Memproses Berkas...';

        setTimeout(function() {
          submitBtn.innerHTML = '<span class="material-symbols-outlined text-[20px]">check_circle</span> Pengajuan Terkirim ke Admin';
          submitBtn.classList.remove('bg-primary');
          submitBtn.classList.add('bg-primary-container', 'text-on-primary-container');

          alert('Selamat! Berkas pendaftaran arena Anda berhasil dikirimkan ke Tim Kurasi locArena. Proses verifikasi berlangsung maksimal 1x24 jam.');
        }, 1200);
      });
    }
  })();
